import{z as d,x as p,o as i,c as B,q as o,j as r,D as n,d as t,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"透镜加热与补偿","description":"","frontmatter":{"title":"透镜加热与补偿","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-heating-compensation.md","filePath":"litho/lens-heating-compensation.md","lastUpdated":1791063341000}'),A={name:"litho/lens-heating-compensation.md"};function m(h,a,D,c,u,f){const l=p("Mermaid");return i(),B("div",null,[a[2]||(a[2]=o('<h1 id="透镜加热与补偿" tabindex="-1">透镜加热与补偿 <a class="header-anchor" href="#透镜加热与补偿" aria-label="Permalink to &quot;透镜加热与补偿&quot;">​</a></h1><div class="epigraph"><p>玻璃吃掉的那一小截 193 nm 变成热。折射率与面形随温度场变，像差跟着扫描历史走，不是一场一个常数。</p><footer>—— 对照投影物镜 lens heating 补偿的公开描述；[Zernike](/litho/zernike-aberrations)</footer></div><p><a href="/litho/catadioptric-lens-design">上一课</a>给出冷态设计。缺口是运行：吸收 → 温度场 → \\(n(T)\\) 与面形 → 波前。本课钉加热与补偿，不重写 Zernike 定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>透过率不是 100%。狭缝里的功率密度随光瞳与掩模透过率变，热场是「这场图形」的函数。刚开机与连扫一小时的像差不同。把套刻/CD 漂移全写成工件台，会漏掉镜头热时间常数（秒到十分钟）。</p><p><span class="marginnote">数字实例：玻璃吸收哪怕只有百分之一二，狭缝里数百瓦照明也意味着瓦级热量持续注入。熔石英 \\(dn/dT\\) 约 \\(10^{-5}\\) /K，10 cm 玻璃升温 3 K，光程就变约 \\(10^{-5}\\times3\\times10\\,\\text{cm}=3\\) nm——纳米级波前预算就这样被吃掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型：若干 Zernike 的加热系数 × 估计功率（剂量、光瞳、掩模开放率）。执行器：后课操纵器、调焦、波长微调。生产：idle 曝光或补偿表随 lot 更新。换高透过掩模等于换热负载。</p>',8)),(i(),r(E,null,{default:n(()=>[s(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E7%8E%BB%E7%92%83%E5%90%B8%E6%94%B6%22%5D%20--%3E%20T%5B%22%E6%B8%A9%E5%BA%A6%E5%9C%BA%22%5D%0A%20%20T%20--%3E%20W%5B%22%E6%B3%A2%E5%89%8D%20%2F%20Zernike%22%5D%0A%20%20W%20--%3E%20CMP%5B%22%E8%A1%A5%E5%81%BF%E8%A1%A8%20%2B%20%E6%93%8D%E7%BA%B5%E5%99%A8%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">补偿是前馈为主：用即将曝光的场预测热，而不是等 CD 坏了再反馈。传感器在镜头里有限，模型误差会变成系统残差。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(dn/dT\\) 与热膨胀改光程。非均匀热场激发球差、像散等轴对称或扫描向模态。时间上像一个低通：脉冲级看不見，场间与 lot 间看见。</p><p><span class="marginnote">直觉类比：镜头热像一台低通滤波器——脉冲级的快抖动被热惯性滤掉，分钟级的场间漂移却原样通过。所以单发曝光看不出加热，连扫半小时的场间 CD 漂移才是它的脸。</span></p><p><span class="marginnote">常见误区：把连扫后的 CD/套刻漂移记到工件台或胶头上。镜头热像差随「刚才扫过什么图形」变——换一张高透过掩模，热负载立刻不同。这是图形相关的慢漂，台子不背这锅。</span></p>',5)),(i(),r(E,null,{default:n(()=>[s(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAD%5B%22%E8%BF%99%E4%B8%80%E5%9C%BA%E7%9A%84%E7%83%AD%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%E5%86%85%E5%8A%9F%E7%8E%87%E5%88%86%E5%B8%83%22%5D%0A%20%20PUP%20--%3E%20MODE%5B%22%E6%BF%80%E5%8F%91%E5%93%AA%E4%BA%9B%20Zernike%20%E6%A8%A1%E6%80%81%22%5D%0A%20%20MODE%20--%3E%20SYM%5B%22%E7%90%83%E5%B7%AE%20%2F%20%E5%83%8F%E6%95%A3%20%2F%20%E7%84%A6%E6%BC%82%22%5D%0A%20%20TC%5B%22%E7%83%AD%E6%97%B6%E9%97%B4%E5%B8%B8%E6%95%B0%20%3D%20%E4%BD%8E%E9%80%9A%22%5D%20--%3E%20SYM%0A%20%20SYM%20--%3E%20FF%5B%22%E5%89%8D%E9%A6%88%E8%A1%A5%E5%81%BF%E8%A1%A8%E6%8C%89%E5%9C%BA%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=e("p",null,"下一课操纵器是执行器细节。致密化（compaction）是剂量积分的永久损伤，不是可逆加热，再后一课。",-1)),a[6]||(a[6]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=e("ul",null,[e("li",null,"镜头热像差随图形与历史变，要前馈补偿。"),e("li",null,"时间常数在场–lot 之间，不在单个脉冲。"),e("li",null,"出处：lens heating 公开实践；Zernike 课。")],-1))])}const k=d(A,[["render",m]]);export{_ as __pageData,k as default};
